# Look for registration forms and components in the src directory
print("\n🔍 SEARCHING FOR REGISTRATION FORMS AND COMPONENTS:")
print("=" * 60)

# Find registration-related components and forms
registration_components = []
form_files = []
page_files = []

# Search for specific registration/form files
for root, dirs, files in os.walk("./src"):
    for file in files:
        if file.endswith(('.tsx', '.ts', '.js', '.jsx')):
            file_path = os.path.join(root, file)
            file_lower = file.lower()

            # Registration components
            if any(keyword in file_lower for keyword in ['register', 'signup', 'cadastro']):
                registration_components.append(file_path)

            # Form files
            if 'form' in file_lower:
                form_files.append(file_path)

            # Page files that might contain registration
            if any(keyword in file_lower for keyword in ['page', 'view', 'screen']):
                page_files.append(file_path)

print(f"\n📝 REGISTRATION COMPONENTS ({len(registration_components)}):")
for file in registration_components:
    print(f"   • {file}")

print(f"\n📋 FORM FILES ({len(form_files)}):")
for file in form_files:
    print(f"   • {file}")

print(f"\n📄 PAGE FILES ({len(page_files)}):")
for file in page_files[:10]:  # Show first 10 to avoid clutter
    print(f"   • {file}")

# Now examine key files to understand the registration flow
key_files_to_examine = [
    "./src/components/Auth/LoginForm.tsx",
    "./src/components/auth/NewLoginForm.tsx",
    "./src/App.tsx"
]

print(f"\n🔍 EXAMINING KEY FILES FOR REGISTRATION FLOW:")
print("=" * 50)

for file_path in key_files_to_examine:
    if os.path.exists(file_path):
        print(f"\n📖 ANALYZING: {file_path}")
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()

            # Look for registration-related keywords in the content
            registration_keywords = ['register', 'signup', 'cadastro', 'criar conta', 'create account']
            found_keywords = []

            for keyword in registration_keywords:
                if keyword.lower() in content.lower():
                    found_keywords.append(keyword)

            if found_keywords:
                print(f"   ✅ Contains registration keywords: {', '.join(found_keywords)}")

                # Show relevant lines
                lines = content.split('\n')
                for i, line in enumerate(lines):
                    if any(kw.lower() in line.lower() for kw in registration_keywords):
                        print(f"   Line {i+1}: {line.strip()}")
                        if i < len(lines) - 1:
                            print(f"   Line {i+2}: {lines[i+1].strip()}")
            else:
                print(f"   ❌ No registration keywords found")

        except Exception as e:
            print(f"   ❌ Error reading file: {e}")
    else:
        print(f"❌ File not found: {file_path}")

# Search for routing configuration to understand how registration is handled
print(f"\n🛤️  SEARCHING FOR ROUTING CONFIGURATION:")
print("=" * 40)

routing_files = []
for root, dirs, files in os.walk("./src"):
    for file in files:
        if file.endswith(('.tsx', '.ts', '.js', '.jsx')):
            file_path = os.path.join(root, file)
            if any(keyword in file.lower() for keyword in ['router', 'route', 'app']):
                routing_files.append(file_path)

print(f"Found {len(routing_files)} routing-related files:")
for file in routing_files[:5]:  # Show first 5
    print(f"   • {file}")

# Check if there are any existing registration pages or modals
print(f"\n🎭 SEARCHING FOR REGISTRATION UI COMPONENTS:")
print("=" * 45)

ui_patterns = [
    'Modal', 'Dialog', 'Form', 'Register', 'SignUp', 'Cadastro'
]

ui_components = []
for root, dirs, files in os.walk("./src/components"):
    for file in files:
        if file.endswith(('.tsx', '.ts')):
            for pattern in ui_patterns:
                if pattern.lower() in file.lower():
                    ui_components.append(os.path.join(root, file))
                    break

print(f"Found {len(ui_components)} UI components that might handle registration:")
for comp in ui_components:
    print(f"   • {comp}")

print(f"\n📊 REGISTRATION SYSTEM ANALYSIS SUMMARY:")
print("=" * 40)
print(f"   • Registration components found: {len(registration_components)}")
print(f"   • Form files available: {len(form_files)}")
print(f"   • Routing files: {len(routing_files)}")
print(f"   • UI components: {len(ui_components)}")

if len(registration_components) == 0 and len([f for f in form_files if 'register' in f.lower()]) == 0:
    print(f"\n🚨 CRITICAL FINDING: No dedicated registration components found!")
    print(f"   This suggests the registration UI might be missing or integrated within login forms.")

# Run a comprehensive test of the registration system to identify specific issues
print("\n🚨 COMPREHENSIVE REGISTRATION SYSTEM DIAGNOSIS:")
print("=" * 60)

# Test 1: Check Supabase configuration and connection
print("\n1️⃣ TESTING SUPABASE CONFIGURATION:")
print("-" * 40)

# Read the Supabase client configuration
try:
    with open("./src/lib/supabase.ts", "r") as f:
        supabase_config = f.read()

    # Check for environment variables in the config
    if "VITE_SUPABASE_URL" in supabase_config and "VITE_SUPABASE_ANON_KEY" in supabase_config:
        print("✅ Supabase client properly configured with environment variables")
    else:
        print("❌ Supabase client missing environment variable usage")

    # Check for hardcoded fallbacks
    if "dmsodonmkffyvbuxtxec.supabase.co" in supabase_config:
        print("⚠️  Hardcoded Supabase URL found as fallback")

    print(f"📄 Supabase config preview (first 500 chars):")
    print(supabase_config[:500] + "..." if len(supabase_config) > 500 else supabase_config)

except Exception as e:
    print(f"❌ Error reading Supabase config: {e}")

# Test 2: Analyze the registration service
print("\n\n2️⃣ ANALYZING REGISTRATION SERVICE:")
print("-" * 40)

registration_issues = []

try:
    # Check the FixedAuthService registration method
    with open("./src/services/fixedAuthService.ts", "r") as f:
        auth_service = f.read()

    # Look for critical registration issues
    if "supabase.auth.signUp" in auth_service:
        print("✅ Supabase signup method found")
    else:
        registration_issues.append("Missing Supabase signup method")

    # Check for profile creation logic
    if "app_2d8133c678_profiles" in auth_service:
        print("✅ Profile table insertion logic found")
    else:
        registration_issues.append("Missing profile creation logic")

    # Check for retry logic
    if "maxAttempts" in auth_service and "while" in auth_service:
        print("✅ Retry logic for profile creation found")
    else:
        registration_issues.append("Missing retry logic for failures")

    # Check error handling
    if "translateError" in auth_service:
        print("✅ Error translation function found")
    else:
        registration_issues.append("Missing error translation")

except Exception as e:
    print(f"❌ Error analyzing registration service: {e}")
    registration_issues.append(f"Cannot read registration service: {e}")

# Test 3: Check database table structure and policies
print("\n\n3️⃣ DATABASE CONFIGURATION ANALYSIS:")
print("-" * 40)

database_issues = []

# Look for any database schema or SQL files
db_files = []
for root, dirs, files in os.walk("."):
    for file in files:
        if file.endswith(('.sql', '.sql.ts', '.sql.js')):
            db_files.append(os.path.join(root, file))

if db_files:
    print(f"✅ Found {len(db_files)} database-related files:")
    for db_file in db_files:
        print(f"   • {db_file}")
else:
    print("⚠️  No database schema files found")
    database_issues.append("Missing database schema documentation")

# Check if there are any policy or security related files
policy_files = []
for root, dirs, files in os.walk("./src"):
    for file in files:
        if any(keyword in file.lower() for keyword in ['policy', 'security', 'rls']):
            policy_files.append(os.path.join(root, file))

if policy_files:
    print(f"✅ Found {len(policy_files)} security/policy files:")
    for policy_file in policy_files:
        print(f"   • {policy_file}")
else:
    print("⚠️  No security policy files found")

# Test 4: Registration form validation
print("\n\n4️⃣ REGISTRATION FORM ANALYSIS:")
print("-" * 40)

form_issues = []

try:
    # Analyze the main registration form
    with open("./src/pages/auth/Register.tsx", "r") as f:
        register_form = f.read()

    # Check for form validation
    if "validateForm" in register_form:
        print("✅ Form validation function found")
    else:
        form_issues.append("Missing form validation")

    # Check for email validation
    if "validateEmail" in register_form:
        print("✅ Email validation found")
    else:
        form_issues.append("Missing email validation")

    # Check for password requirements
    if "password.length" in register_form:
        print("✅ Password length validation found")
    else:
        form_issues.append("Missing password validation")

    # Check for terms acceptance
    if "acceptedTerms" in register_form:
        print("✅ Terms acceptance check found")
    else:
        form_issues.append("Missing terms acceptance")

    # Check for user type handling
    if "userType" in register_form and ("client" in register_form and "writer" in register_form):
        print("✅ User type selection found")
    else:
        form_issues.append("Missing user type selection")

except Exception as e:
    print(f"❌ Error analyzing registration form: {e}")
    form_issues.append(f"Cannot read registration form: {e}")

# Test 5: Check for common authentication issues
print("\n\n5️⃣ COMMON AUTHENTICATION ISSUES CHECK:")
print("-" * 40)

auth_issues = []

# Check environment files
env_files = [".env", ".env.local"]
for env_file in env_files:
    if os.path.exists(env_file):
        try:
            with open(env_file, "r") as f:
                env_content = f.read()
            if "VITE_SUPABASE_URL" in env_content and "VITE_SUPABASE_ANON_KEY" in env_content:
                print(f"✅ {env_file} contains required Supabase variables")
            else:
                auth_issues.append(f"{env_file} missing Supabase configuration")
        except Exception as e:
            auth_issues.append(f"Cannot read {env_file}: {e}")
    else:
        auth_issues.append(f"{env_file} file missing")

# Check for CORS or network issues
if "localhost" in auth_service or "127.0.0.1" in auth_service:
    print("⚠️  Local development URLs found - ensure proper CORS setup")

# Test 6: Potential Supabase Auth Issues
print("\n\n6️⃣ SUPABASE AUTH CONFIGURATION ISSUES:")
print("-" * 40)

supabase_issues = [
    {
        "issue": "Email Confirmation",
        "description": "Supabase may require email confirmation by default",
        "solution": "Disable email confirmation in Supabase Auth settings or handle confirmation flow"
    },
    {
        "issue": "Sign-up Restrictions", 
        "description": "Sign-up might be disabled in Supabase Auth settings",
        "solution": "Enable sign-up in Supabase Dashboard > Authentication > Settings"
    },
    {
        "issue": "Row Level Security (RLS)",
        "description": "RLS policies might block profile creation",
        "solution": "Check RLS policies on app_2d8133c678_profiles table"
    },
    {
        "issue": "Table Permissions",
        "description": "Anonymous users might not have INSERT permissions",
        "solution": "Grant INSERT permissions to authenticated users on profiles table"
    }
]

for issue in supabase_issues:
    print(f"⚠️  {issue['issue']}: {issue['description']}")
    print(f"   🔧 Solution: {issue['solution']}")

# Final diagnosis summary
print("\n\n🎯 FINAL DIAGNOSIS SUMMARY:")
print("=" * 50)

all_issues = registration_issues + database_issues + form_issues + auth_issues

if not all_issues:
    print("✅ No obvious code issues found in registration system")
    print("🔍 Issue likely in Supabase configuration:")
    print("   • Check if sign-up is enabled in Supabase Auth settings")
    print("   • Verify email confirmation is disabled or properly handled")
    print("   • Check RLS policies on the profiles table")
    print("   • Ensure anonymous users can INSERT into profiles table")
else:
    print("❌ IDENTIFIED ISSUES:")
    for i, issue in enumerate(all_issues, 1):
        print(f"   {i}. {issue}")

print("\n🚀 RECOMMENDED IMMEDIATE ACTIONS:")
print("1. Check Supabase Dashboard > Authentication > Settings")
print("2. Verify 'Enable email confirmations' is OFF or handle confirmation")
print("3. Ensure 'Enable sign up' is ON") 
print("4. Check Database > app_2d8133c678_profiles table RLS policies")
print("5. Test registration with browser console open to see exact error messages")

