    email: 'test@invalid-domain-for-testing.com',
    password: 'test123456'
  });

  console.log('Test signup result - Data:', data, 'Error:', error);

  if (error) {
    console.log('Error type:', error.status);
    console.log('Error message:', error.message);
    console.log('Full error:', error);
  }

} catch (error) {
  console.error('❌ Registration error test failed:', error);
}

console.log('\\n🎯 DIAGNOSTIC COMPLETE');
console.log('Check the output above for specific error details');
"""

# Write the detailed test script
with open("./detailed-registration-diagnostic.js", "w") as f:
    f.write(detailed_test_script)

print(f"\n\n📋 DETAILED DIAGNOSTIC SCRIPT CREATED:")
print("✅ Saved to: ./detailed-registration-diagnostic.js")

# Check current Supabase configuration for common issues
print(f"\n\n3️⃣ SUPABASE CONFIGURATION CHECK:")
print("-" * 40)

try:
    with open("./src/lib/supabase.ts", "r") as f:
        supabase_config = f.read()

    # Look for specific configuration issues
    config_issues = []

    if "import.meta.env.VITE_SUPABASE_URL" not in supabase_config:
        config_issues.append("Environment variable not properly used for URL")

    if "import.meta.env.VITE_SUPABASE_ANON_KEY" not in supabase_config:
        config_issues.append("Environment variable not properly used for ANON_KEY")

    # Check for auth configuration
    if "auth:" in supabase_config:
        print("✅ Auth configuration found in Supabase client")
    else:
        config_issues.append("No specific auth configuration found")

    if config_issues:
        print("⚠️  CONFIGURATION ISSUES:")
        for issue in config_issues:
            print(f"   • {issue}")
    else:
        print("✅ Supabase configuration looks correct")

    # Show critical parts of config
    lines = supabase_config.split('\n')
    print(f"\n📄 KEY CONFIGURATION LINES:")
    for i, line in enumerate(lines):
        if any(keyword in line for keyword in ['createClient', 'supabaseUrl', 'supabaseKey', 'export']):
            print(f"   Line {i+1}: {line.strip()}")

except Exception as e:
    print(f"❌ Error reading Supabase config: {e}")

# Check environment files for completeness
print(f"\n\n4️⃣ ENVIRONMENT FILES VALIDATION:")
print("-" * 40)

env_files = [".env", ".env.local"]
for env_file in env_files:
    if os.path.exists(env_file):
        try:
            with open(env_file, "r") as f:
                content = f.read()

            print(f"\n📄 {env_file}:")
            required_vars = ["VITE_SUPABASE_URL", "VITE_SUPABASE_ANON_KEY"]

            for var in required_vars:
                if var in content:
                    # Extract the value (safely, without showing full key)
                    for line in content.split('\n'):
                        if line.startswith(var):
                            if "supabase.co" in line:
                                print(f"   ✅ {var}: URL configured")
                            elif len(line.split('=')[1].strip()) > 20:
                                print(f"   ✅ {var}: Key configured (length: {len(line.split('=')[1].strip())})")
                            else:
                                print(f"   ⚠️  {var}: Value seems short")
                            break
                else:
                    print(f"   ❌ {var}: MISSING")

        except Exception as e:
            print(f"   ❌ Error reading {env_file}: {e}")
    else:
        print(f"❌ {env_file}: File not found")

# Create a comprehensive error identification guide
print(f"\n\n🎯 MOST LIKELY ERROR CAUSES:")
print("=" * 50)

likely_causes = [
    {
        "cause": "Email Confirmation Required",
        "probability": "HIGH",
        "description": "Supabase requires email confirmation but user never confirms",
        "test": "Check if signup returns success but user can't login",
        "fix": "Disable email confirmation in Supabase Auth settings"
    },
    {
        "cause": "RLS Policy Blocking Profile Creation",
        "probability": "HIGH", 
        "description": "Row Level Security prevents inserting into profiles table",
        "test": "Signup succeeds but profile creation fails",
        "fix": "Update RLS policies to allow authenticated users to INSERT"
    },
    {
        "cause": "Signup Disabled in Supabase",
        "probability": "MEDIUM",
        "description": "Signup is turned off in Supabase Auth settings",
        "test": "Signup returns 'signups not allowed' error",
        "fix": "Enable signup in Supabase Dashboard > Authentication > Settings"
    },
    {
        "cause": "Invalid Supabase Credentials",
        "probability": "MEDIUM",
        "description": "URL or API key is incorrect or expired",
        "test": "All Supabase operations fail",
        "fix": "Verify credentials in Supabase Dashboard > Settings > API"
    },
    {
        "cause": "Table Schema Mismatch",
        "probability": "LOW",
        "description": "Profile table structure doesn't match insert data",
        "test": "Profile insertion fails with schema error",
        "fix": "Check table schema matches the data being inserted"
    }
